using FluentAssertions;
using WhatsBiz.Application.Features.Suppliers;
namespace WhatsBiz.Tests.Suppliers;
public sealed class SupplierValidatorTests { [Fact] public async Task ValidIndianTaxIdentifiersPass() { var r = await new SupplierInputValidator().ValidateAsync(Input()); r.IsValid.Should().BeTrue(); } [Theory][InlineData("INVALID", "ABCDE1234F")][InlineData("27ABCDE1234F1Z5", "BADPAN")] public async Task InvalidTaxIdentifierFails(string gst, string pan) { var r = await new SupplierInputValidator().ValidateAsync(Input() with { GSTIN = gst, PAN = pan }); r.IsValid.Should().BeFalse(); } [Fact] public async Task InvalidEmailAndMobileFail() { var r = await new SupplierInputValidator().ValidateAsync(Input() with { Email = "bad", Mobile = "123" }); r.Errors.Should().Contain(x => x.PropertyName == nameof(SupplierInput.Email)); r.Errors.Should().Contain(x => x.PropertyName == nameof(SupplierInput.Mobile)); } private static SupplierInput Input() => new("SUP-1", "Supplier One", "Domestic", "27ABCDE1234F1Z5", "ABCDE1234F", null, "one@example.com", "9876543210", null, null, "INR", null, 1000, 0, true, false, true, null, [], [], []); }
